import{n as e,s as t,t as n}from"./jsx-runtime-D8nDyRPw.js";import{Dt as r,J as i,Y as a,Z as o,bt as s,q as c,t as l}from"./index-DtKy-6o9.js";import{t as u}from"./surya-CIZRROiK.js";var d=t(e(),1),f=`/assets/surya2-DtKrjNH3.jpeg`,p=`/assets/surya3-CR3Km08h.jpeg`,m=`/assets/surya4-DyQ6M_np.jpeg`,h=`/assets/surya5-Dq0VEPwt.jpeg`,g=n(),_=[{id:`what-is`,label:`What is Sauram?`},{id:`pramanas`,label:`6 Pramanas`},{id:`upasana`,label:`5 Classifications`},{id:`yantra`,label:`Yantra & Mantra`},{id:`importance`,label:`Why Today`},{id:`relations`,label:`Divine Relation`},{id:`essence`,label:`Essence & Practice`}],v=[{veda:`Rig Veda 1.50 — Surya Mantra`,says:`“Ud Utyam Jatavedasam” — “The Sun, the Jatavedas, is carried by the rays to be seen by all.” The rising Sun is prayed to as the visible, all-seeing divine.`},{veda:`Rig Veda 3.62.10 — Gayatri Mantra`,says:`The Gayatri is offered by sage Vishvamitra to Savitar — the Sun as the impeller of all. “Tat Savitur Varenyam… dhiyo yo nah prachodayat” — may the Sun-Guide illumine our intellects.`},{veda:`Rig Veda 1.89.10 — Aditi & the Adityas`,says:`“Aditir Dyauh, Aditir Antariksham” — Aditi is heaven, Aditi is the mid-region. Rig Veda names Aditi the mother of the Adityas — the forms of the Sun.`},{veda:`Yajur Veda — Eye of the Universe`,says:`The Yajur Veda declares Surya “Suryo Jyotisham Jyotih” — the light of all lights, the eye of the world that witnesses all actions.`},{veda:`Atharva Veda — Prayer for Health`,says:`The Atharva Veda prays to the Sun for long life, clear sight, and the dispelling of darkness and disease from the body.`},{veda:`Gayatri / Savitri Upanishad`,says:`The Saura Upanishadic tradition meditates on the golden person within the solar orb as Brahman — the Sun seen from outside is its body, the Self is its light.`}],y=[{name:`Saura Purana`,detail:`The primary scripture of the Sauram path. It instructs the worship of Surya as Brahman, the forms of the Sun, the Surya Mantra, and the rites of the Saura Agama. One of the sacred texts traditionally dedicated to the Sun.`},{name:`Bhavishya Purana`,detail:`Preserves the Savitri Mantra tradition and the daily worship of the Sun at dawn. It promises that he who worships Surya with the Gayatri shines like the Sun — the Sun is honoured as the creator of the day and the witness of all deeds.`},{name:`Samba Purana`,detail:`Samba, son of Krishna, is said to have worshipped Surya in penance and to have built the first great Surya temples. This text details temple worship of the Sun, the Surya Murti and the twelve Adityas.`},{name:`Vishnu Purana`,detail:`Lists the twelve Adityas as forms of one divine being, and describes the chariot of the Sun drawn by seven horses — the radiant wheel of time that measures the day, the season and the year of all creation.`}],b=[{name:`Ramayana — Surya Vamsha`,detail:`Rama is born in the Surya Vamsha — the Solar dynasty. Before the final battle with Ravana, Sage Agastya teaches Rama the Aditya Hridaya Stotra praising the twelve names of the Sun (Valmiki Ramayana, Yuddha Kanda 107).`},{name:`Bhagavad Gita 15.12`,detail:`Krishna says: “Yad Aditya-gatan Tejo… tat tejo viddhi mamakam” — the light that shines in the Sun is My light. The Sun is called the eye and the lamp of the universe.`},{name:`Mahabharata — Karna`,detail:`Karna, the greatest of Surya’s devotees, prays to the setting Sun every evening through the Mahabharata. Surya grants him the divine Kavacha and Kundala — the armour that could not be pierced (Vana Parva).`},{name:`Mahabharata — Surya’s Chariot`,detail:`The epic describes Surya’s chariot drawn by seven horses — the seven colours and the seven metres of the Veda — carrying time itself across the sky from east to west.`}],x=[{name:`Saura Agama`,detail:`The ritual code of the Sun temples — the Surya Murti facing East, the Arka flower, the red lotus and the daily Arghya offered at dawn. The Saura Agama governs the great solar shrines such as Konark and Modhera.`},{name:`Surya Tantra`,detail:`Meditation on the Surya Mandala — the twelve-rayed wheel of the morning Sun. The Sun is interpreted as the Self within; the inner Sun is given the name Tvam-eva — “Thou art That.”`},{name:`Surya Beeja — Seed Syllable`,detail:`The sacred single syllable of the Sun is Hram. Combined with Om and the name of Surya it forms the Surya Maha-Mantra — the central formula of the Surya Tantra.`},{name:`Aru — The Six Rays`,detail:`Traditionally the Sun is meditated upon with six rays (Aru) governing the six seasons and the six centres of life in the body — purifying perception, breath and vitality.`}],S=[{field:`Source of All Energy`,says:`Every form of energy on Earth — food, wood, oil, wind, water — traces back to sunlight. The shastras call it Prana; the sciences call it photosynthesis. Both point to one truth: the Sun is the giver of life.`},{field:`Vitamin D & the Body Clock`,says:`Sunlight produces Vitamin D and sets the circadian rhythm — the biological clock that governs sleep, immunity and mood. Modern medicine confirms what the Gayatri assumed: the Sun rules our health.`},{field:`Solar Science`,says:`Astronomy measures the Sun as the beating heart of the solar system, holding 99.8% of its mass. The ancient seers had no telescopes — they saw the same Sun as Brahman through inner vision.`},{field:`Ancient Accuracy`,says:`The Surya Siddhanta computed the length of the year, the seasons and the eclipses with remarkable precision. Surya upasana is not superstition — it is reverence for the physical source of every life.`}],C=[{form:`Udaya Aditya — Rising Sun`,brahma:`Brahma`,work:`Creation`,practice:`Morning worship — Surya Arghya with water, Gayatri japa, prostration to the rising Sun.`},{form:`Madhyahna Aditya — Midday Sun`,brahma:`Vishnu`,work:`Preservation`,practice:`Midday puja — the Sun at full power sustains the world and the vital fire of the body.`},{form:`Astamaya Aditya — Setting Sun`,brahma:`Shiva / Rudra`,work:`Dissolution`,practice:`Evening prayer — surrender of the day; the setting Sun gathers all things into rest.`}],w=[{name:`Amshuman`,meaning:`The Rayed One`,role:`All light is His`},{name:`Aryaman`,meaning:`The Noble Companion`,role:`Patronage, friendship, honour`},{name:`Indra`,meaning:`Divine Power`,role:`Strength, kingship, victory`},{name:`Tvashta`,meaning:`The Divine Craftsman`,role:`Creator of living forms`},{name:`Varuna`,meaning:`Cosmic Order (Rta)`,role:`Waters and universal law`},{name:`Dhata`,meaning:`The Supporter`,role:`Upholder of all worlds`},{name:`Mitra`,meaning:`The Friendly Light`,role:`Harmony and alliance`},{name:`Parjanya`,meaning:`The Rain-God`,role:`Nourishment from the sky`},{name:`Vivasvan`,meaning:`The Shining One`,role:`The dawning Sun`},{name:`Pushan`,meaning:`The Nourisher`,role:`Growth, cattle, journeys`},{name:`Bhaga`,meaning:`The Fortunate`,role:`Bliss and prosperity`},{name:`Vishnu`,meaning:`The All-Pervading`,role:`Preserver of all`}],T=[{name:`Northern Saura Sampradaya`,detail:`The grand solar temples — Konark (Surya Deula), Modhera, Martand in Kashmir and Biranchi Narayan in Odisha. Gayatri is chanted at sunrise; the great wheel of Konark is the Surya Chandrasa — the turning year of Brahman realised in stone. The Saurya Agama governs the temple.`},{name:`Southern Saura Sampradaya`,detail:`Surya stands at the centre of Navagraha and Panchayatana worship. The Navagraha temple at Suryanar Kovil, Kumbakonam, and the solar shrines of Tamil Nadu honour the Sun as the king of planets. Aruna — the dawn-charioteer — is chanted at sunrise.`}],E=[{num:`I`,goal:`Moksha — Liberation`,way:`Brahma-Surya Jnana`,detail:`Worship the Sun as Brahman — the Self of all. The Saura Purana and the Gayatri Upanishad teach meditation on the golden person in the orb as liberation itself.`,shastra:`Saura Purana`},{num:`II`,goal:`Health & Long Life`,way:`Surya Namaskara + Aditya Mantra`,detail:`Twelve prostrations at dawn and Japa of Om Suryaya Namah restore the vital fire, sharpen the eyes and lengthen life.`,shastra:`Yoga + Ayurveda`},{num:`III`,goal:`Prosperity & Authority`,way:`Raja-Surya Puja`,detail:`Surya is the king of planets. Puja on Sunday grants command, status, success in administration and strength of speech.`,shastra:`Jyotisha`},{num:`IV`,goal:`Victory & Renown`,way:`Aditya Hridaya Stotra`,detail:`Recited before battle, the Aditya Hridaya granted Rama victory. In daily life it grants courage, fame and the defeat of inner enemies.`,shastra:`Valmiki Ramayana`}],D=[{num:`1`,color:`Red`,chakra:`Muladhara`,quality:`Stability & Grounding`},{num:`2`,color:`Orange`,chakra:`Swadhisthana`,quality:`Creativity & Vitality`},{num:`3`,color:`Yellow`,chakra:`Manipura`,quality:`Power & Will`},{num:`4`,color:`Green`,chakra:`Anahata`,quality:`Love & Compassion`},{num:`5`,color:`Blue`,chakra:`Vishuddha`,quality:`Truth & Speech`},{num:`6`,color:`Indigo`,chakra:`Ajna`,quality:`Wisdom & Insight`},{num:`7`,color:`Violet / White`,chakra:`Sahasrara`,quality:`Liberation & Bliss`}],O=[{num:`I`,point:`Pratyaksha — The Visible God`,detail:`The only major deity you can see with your own eyes every day. No image is required — darshan is guaranteed by dawn.`,shastra:`Sanatana tradition`},{num:`II`,point:`Gayatri — Mother of Mantras`,detail:`The foremost mantra of the Vedas is addressed to Savitar, the Sun — the divine impeller of the intellect.`,shastra:`Rig Veda 3.62.10`},{num:`III`,point:`Health & Vitality`,detail:`Sunlight is the source of physical vitality; Surya Namaskara opens the body, breath and mind to prana.`,shastra:`Ayurveda + Yoga`},{num:`IV`,point:`Time & Jyotisha`,detail:`The Sun rules the calendar, the seasons, the planets and the soul — Surya is Atmakaraka, the significator of the Self.`,shastra:`Surya Siddhanta`},{num:`V`,point:`Energy & Life`,detail:`All life-energy on Earth originates from the Sun — seen in the Veda as Prana itself and confirmed by modern science.`,shastra:`Modern Science`},{num:`VI`,point:`Unity of the Six Paths`,detail:`Surya is honoured in every sampradaya — as Vishnu of the solar orb, as Shiva in the setting sun, as the Gayatri-Shakti of all mantras.`,shastra:`Shanmata`}],k=[{name:`Vishnu`,relation:`Solar Eye`,meaning:`Surya Narayana — Vishnu dwells within the solar orb; Krishna says the light of the Sun is His light. Rama of the Surya Vamsha carries the solar line into the Ramayana.`},{name:`Shiva`,relation:`Solar Rest`,meaning:`The setting Sun is meditated upon as the form of Rudra — the one who gathers all things into rest. The Samba Purana links Shiva and Surya directly through Samba’s penance.`},{name:`Shakti`,relation:`Solar Power`,meaning:`Gayatri is the mother of the mantras — the Shakti of the Sun. Savitri is the feminine divine who illumines the mind. Surya + Shakti = light and power together.`},{name:`Parabrahman`,relation:`One Light`,meaning:`Sauram says the Sun is Brahman; Vaishnavam sees Vishnu in the orb; Shaivam sees Shiva; Shaktam sees the Goddess; Kaumaram sees the fire of the Sun. One Sun — one Self — seen through many forms.`}],A=[{label:`Pratyaksha`,title:`Direct Vision`,text:`The Sun is beheld daily — worship begins with seeing. Sauram’s first pillar is darshan of the visible Brahman.`},{label:`Gayatri`,title:`Sacred Sound`,text:`The Gayatri mantra is the sound-body of the Sun. Japa at sunrise tunes the mind to solar intelligence.`},{label:`Surya Namaskara`,title:`Sacred Action`,text:`Twelve prostrations join body, breath and devotion — the Sun is greeted by the whole being.`}],j=[{label:`Morning`,title:`Surya Arghya + Gayatri`,text:`<em>Om Suryaya Namah</em> — 108 times at sunrise, with water offered to the rising Sun. Gayatri japa — 10 times.`},{label:`Sunday`,title:`Surya’s Day`,text:`Optional fast on Sunday; recite the Aditya Hridaya Stotra; offer red flowers, red sandal and water; wear red or orange — traditional.`},{label:`Evening`,title:`Thanksgiving`,text:`Offer gratitude to the setting Sun; one reading of the Aditya Hridaya; sleep early — the solar rhythm heals.`}];functio